// LLM Caller — replaces AI Agent + Gemini + Parser (Gateway blocked custom models).
// Calls 9router OpenAI-compatible endpoint with your key, parses strict JSON itself.
// Input: Compute Indicators output. Output: {json:{output:{decision,signal,backtest,...}}}
const src = $input.first().json;
const F = src.features || {};
const SYS = `ROLE: macro-aware crypto quant-research agent inside a scheduled n8n workflow. Fuse macro, news, sentiment, derivatives, technicals into ONE low-risk signal or justified NO_TRADE. Conservative: rejecting weak setups is success. Analysis only, not financial advice. Never invent numbers; every number comes from workflow input.
