const body = { model: 'claude-fable-5-1', messages: [{ role: 'system', content: SYS }, { role: 'user', content: SNAP + '\n\nRespond with STRICT JSON only, no markdown, no commentary.' }], temperature: 0.2, max_tokens: 1500 };
